@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 15px;
  line-height: 1.55;
  color: #2b3236;
  background: #ffffff;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 22px 64px;
}

.logo {
  font-size: 19px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #4d585e;
}

.hero {
  height: 430px;
  padding: 72px 64px 0;
}

.hero-text {
  max-width: 400px;
}

h1 {
  margin: 0 0 16px;
  font-size: 30px;
  font-weight: 500;
  line-height: 1.25;
}

.hero-text p {
  margin: 0 0 24px;
  color: #4d585e;
}

.button {
  display: inline-block;
  padding: 11px 20px;
  border-radius: 6px;
  background: #1f5f7a;
  color: #ffffff;
  text-decoration: none;
  font-weight: 500;
}

.lower {
  display: flex;
  gap: 48px;
  padding: 0 64px;
}

.today {
  flex: 0 0 300px;
}

h2 {
  margin: 0 0 6px;
  font-size: 13px;
  font-weight: 500;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 12px;
  color: #4d585e;
}

th,
td {
  padding: 2px 0;
  text-align: left;
  font-weight: 400;
}

th {
  color: #7a858b;
}

.points {
  display: flex;
  gap: 32px;
}

.point h3 {
  margin: 0 0 4px;
  font-size: 15px;
  font-weight: 500;
}

.point p {
  margin: 0;
  color: #4d585e;
}

.point {
  flex: 1;
}

